83:     pub fn decide(
84:         self,
85:         failure: &StepFailure,
86:         safety: RetrySafety,
87:         snapshot: RecoverySnapshot,
88:     ) -> RecoveryDecision {
89:         if safety == RetrySafety::EffectOutcomeUnknown {
90:             return RecoveryDecision::Reconcile;
91:         }
92:         if snapshot.deadline <= snapshot.now {
93:             return RecoveryDecision::FailRun(RecoveryLimit::Deadline);
94:         }
95:         if snapshot.work_budget == RetryEligibility::Exhausted {
96:             return RecoveryDecision::FailRun(RecoveryLimit::WorkBudget);
97:         }
98:         if failure.class() == FailureClass::Terminal
99:             || snapshot.attempts.consumed == snapshot.attempts.limit
100:         {
101:             return RecoveryDecision::FinalError;
102:         }
103:         // Clamp the exponent before shifting; even extreme persisted counters
104:         // take constant work. Saturation cannot wrap a large delay back to zero.
105:         let multiplier = 1_u32 << (snapshot.attempts.consumed - 1).min(31);
106:         let delay = self.initial.saturating_mul(multiplier).min(self.maximum);
107:         // Validated maximum fits chrono. checked_add also handles extreme dates.
108:         let Some(retry_at) = TimeDelta::from_std(delay)
109:             .ok()
110:             .and_then(|delay| snapshot.now.checked_add_signed(delay))
111:         else {
112:             return RecoveryDecision::FailRun(RecoveryLimit::Deadline);
113:         };
114:         if retry_at >= snapshot.deadline {
115:             return RecoveryDecision::FailRun(RecoveryLimit::Deadline);
116:         }
117:         RecoveryDecision::RetryAt(retry_at)
118:     }

