186: pub fn resolve_outcome<'a>(
187:     workflow: &'a ValidatedWorkflow,
188:     step: &StepId,
189:     outcome: &'a StepOutcome,
190:     retry: RetryEligibility,
191:     now: DateTime<Utc>,
192: ) -> Result<EngineDisposition<'a>, OutcomeError> {
193:     if !workflow.definition().steps.contains_key(step) {
194:         return Err(RouteError::UnknownStep(step.clone()).into());
195:     }
196:     match outcome {
197:         StepOutcome::Completed(completed) => {
198:             super::context::validate_output(completed.output(), workflow.context_limits())?;
199:             let selection = match completed.route() {
200:                 CompletionRoute::Success => RouteSelection::Success,
201:                 CompletionRoute::Choice(choice) => RouteSelection::Choice(choice.clone()),
202:             };
203:             let target = select_route(workflow, step, &selection)?;
204:             Ok(EngineDisposition::Advance { completed, target })
205:         }
206:         StepOutcome::Waiting(request) => {
207:             if request.deadline() <= now {
208:                 return Err(OutcomeError::ExpiredDeadline);
209:             }
210:             Ok(EngineDisposition::Park { request })
211:         }
212:         StepOutcome::Failed(failure)
213:             if failure.class() == FailureClass::Retryable
214:                 && retry == RetryEligibility::Available =>
215:         {
216:             Ok(EngineDisposition::Retry { failure })
217:         }
218:         StepOutcome::Failed(failure) => {
219:             let target = match select_route(workflow, step, &RouteSelection::FinalError) {
220:                 Ok(target) => Some(target),
221:                 Err(RouteError::MissingFinalError(_)) => None,
222:                 Err(error) => return Err(error.into()),
223:             };
224:             Ok(EngineDisposition::Terminal { failure, target })
225:         }
226:     }
227: }
